 public static class Mathf {public const float Rad2Deg=57.29578f;public static float Min(float a,float b){return Math.Min(a,b);}public static float Max(float a,float b){return Math.Max(a,b);}public static float Clamp(float a,float b,float c){return Math.Min(c,Math.Max(a,b));}public static float Clamp01(float a){return Clamp(a,0,1);}public static float Sqrt(float a){return (float)Math.Sqrt(a);}public static float Atan2(float a,float b){return (float)Math.Atan2(a,b);}public static int CeilToInt(float a){return (int)Math.Ceiling(a);}}
