public partial class ServiceStops:UnityEngine.MonoBehaviour {
 public DriveSession session;public string destination="",notice="";float noticeUntil;public bool open;public readonly List<int> Bought=new List<int>();
 public List<FuelStationLayout.FuelStation> Stations=new List<FuelStationLayout.FuelStation>();public RestaurantSiteLayout.Site Restaurant;public FuelStationLayout.FuelStation RestArea;public MapStop MealStop=new MapStop(),ParkingStop=new MapStop();public UnityEngine.Vector3 MealPosition{get{return MealStop.V();}}public MapStop StopFor(int kind){return ParkingStop;}public bool CanUse(int action){return true;}void Close(bool p){open=false;}
 public bool Buy(int action){Bought.Add(action);var e=session.business.ledger;if(action==0){e.Account.Refuel("fixture:"+Bought.Count,Math.Min(10,100-e.Account.Fuel),e.Day);e.AdvanceService(10);}else if(action==4)e.UseWash("fixture:"+Bought.Count);else if(action==5)e.UseRepair("fixture:"+Bought.Count);return true;}
}
public static class OperationPlanningAdapterTests {
 static void Check(bool b,string text){if(!b)throw new Exception(text);}
 static void Set(object o,string name,object value){o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,value);}
 static DriveSession Session(PvpSimulationMatch match){var s=new DriveSession{simulationMatch=match,IsSimulationBot=true};s.services=new ServiceStops{session=s};return s;}
 static FacilityOption Site(){return new FacilityOption{Id="0.0:20.0",Approach=new MapStop(),Bay=new UnityEngine.Vector3(0,0,20),Direction=UnityEngine.Vector3.forward,TravelSeconds=1,TravelMetres=1,Entry=new[]{UnityEngine.Vector3.zero,new UnityEngine.Vector3(0,0,20)},Departure=new[]{new UnityEngine.Vector3(0,0,20),new UnityEngine.Vector3(0,0,40)}};}
 static void CriticalCaller(){ProjectMapScene.Authored=true;try{for(int condition=0;condition<4;condition++){var s=Session(new PvpSimulationMatch());if(condition==0)s.business.ledger.Account.Consume(0,59000/4);if(condition==1)s.business.ledger.Driver.fatigue=90;if(condition==2)s.business.ledger.Care.MarkVomit();if(condition==3){s.business.ledger.Care.Damage.Impact(16);s.business.ledger.Care.Damage.Advance(1,false);s.business.ledger.Care.Damage.Impact(12);}var bot=new PvpSimulationBotServices();Check(bot.Tick(s),"critical selection failure must retain caller control condition="+condition);Check(bot.Tick(s),"critical retry cooldown must retain caller control condition="+condition);Check(s.taxi.autoBrake,"critical retry safely stops taxi condition="+condition);}}finally{ProjectMapScene.Authored=false;}}
 static void EntranceAdvances(){var match=new PvpSimulationMatch();var a=Session(match);var b=Session(match);var site=Site();Check(a.services.CanEnterFacility(site),"owner admitted");Check(!b.services.CanEnterFacility(site),"second entrance ticket waits");a.taxi.transform.position=site.Bay;a.services.TickFacilityQueue();a.taxi.transform.position=site.Bay+site.Direction*25;b.services.TickFacilityQueue();Check(!b.services.QueueWaiting,"real Tick releases departed owner and advances entrance ticket with no purchase action");Check(a.business.ledger.Elapsed==0&&b.business.ledger.Elapsed==0&&a.business.ledger.Account.Entries.Length==0&&b.business.ledger.Account.Entries.Length==0,"queue advancement creates no native service charge or time");}
 static void CancelStaysCanceled(){var s=Session(new PvpSimulationMatch());s.IsSimulationBot=false;var site=Site();s.taxi.transform.position=site.Bay;var station=new FuelStationLayout.FuelStation{approach=site.Approach,pump=site.Bay,direction=site.Direction,drivePath=new[]{site.Approach.V(),site.Bay,site.Bay+site.Direction*20}};s.services.Stations.Add(station);s.services.CanEnterFacility(site);s.services.CancelQueue();UnityEngine.Time.time=1;UnityEngine.Time.unscaledTime=1;s.services.TickFacilityQueue();Check(s.services.QueueStatus=="","cancel must survive actual eligibility Tick while still in driveway");UnityEngine.Time.time=2;s.services.TickFacilityQueue();UnityEngine.Time.time=3;s.services.TickFacilityQueue();Check(s.services.QueueStatus=="","cancel suppression persists across repeated actual Ticks");Check(s.services.GuideFacility(site),"explicit new selection accepted");UnityEngine.Time.time=4;s.services.TickFacilityQueue();Check(s.services.QueueStatus!="","explicit selection restores entrance eligibility");s.services.CancelQueue();s.taxi.transform.position=new UnityEngine.Vector3(0,0,200);UnityEngine.Time.time=5;s.services.TickFacilityQueue();s.taxi.transform.position=site.Bay;UnityEngine.Time.time=6;s.services.TickFacilityQueue();Check(s.services.QueueStatus!="","physical departure and return restores eligibility");}
 static void ExecutesPlanOnly(){var s=Session(new PvpSimulationMatch());s.business.ledger.Account.Consume(0,36000/4);s.business.ledger.Care.Damage.Impact(12);s.business.ledger.Care.Damage.Advance(1,false);s.business.ledger.Care.Damage.Impact(2);var bot=new PvpSimulationBotServices();Set(bot,"stage",3);Set(bot,"kind",0);Set(bot,"approach",new MapStop());Set(bot,"direction",UnityEngine.Vector3.forward);Set(bot,"departure",new[]{UnityEngine.Vector3.zero,UnityEngine.Vector3.forward*20});bot.Tick(s);Check(s.services.Bought.Count==1&&s.services.Bought[0]==0,"fuel plan cannot silently purchase repair or wash");bot.Tick(s);Check(s.services.Bought.Count==1,"one planned fuel increment cannot repeat purchases to60");Check(s.business.ledger.Account.Expense(1,"repair")==0&&s.business.ledger.Account.Expense(1,"wash")==0&&s.business.ledger.Account.Expense(1,"fuel")==400,"native ledger contains exactly the planned400 fuel expense");}
 static void DrivewayBudget(){var s=Session(new PvpSimulationMatch());s.taxi.transform.position=new UnityEngine.Vector3(0,0,-20);var site=Site();s.services.Stations.Add(new FuelStationLayout.FuelStation{approach=site.Approach,pump=site.Bay,direction=site.Direction,drivePath=new[]{site.Approach.V(),site.Bay,site.Bay+site.Direction*20}});var option=s.services.FacilityOptions(0)[0];Check(option.TravelSeconds>28,"facility decision travel must include authored entry and exit at physical manoeuvre speed");Check(option.Quote.TravelSeconds>19,"native quote must consume actual entry travel before planned service");}
 static void MealThroughAccess(){ProjectMapScene.Authored=true;try{var s=Session(new PvpSimulationMatch());s.world.map.mapId="pvp-city-a";var bay=new UnityEngine.Vector3(10,0,20);ProjectMapScene.Restaurant=new ProjectMapObject{id="city:meal:4",name="meal",Position=bay,Direction=UnityEngine.Vector3.forward};s.world.map.roads=new[]{new MapRoad{id="city:start:4:access",points=new[]{new MapPoint{value=new UnityEngine.Vector3(0,0,0)},new MapPoint{value=new UnityEngine.Vector3(10,0,10)},new MapPoint{value=new UnityEngine.Vector3(10,0,30)},new MapPoint{value=new UnityEngine.Vector3(0,0,40)}}}};var option=s.services.FacilityOptions(1)[0];Check(option.Entry[1].z==10&&option.Departure[1].z==30,"city meal follows authored through driveway instead of reversing entrance");}finally{ProjectMapScene.Authored=false;ProjectMapScene.Restaurant=null;}}
 static void RemoteHumanQueues(){PvpNativeLan.Remote=true;try{var s=Session(new PvpSimulationMatch());var site=Site();s.services.Stations.Add(new FuelStationLayout.FuelStation{approach=site.Approach,pump=site.Bay,direction=site.Direction,drivePath=new[]{site.Approach.V(),site.Bay,site.Bay+site.Direction*20}});s.taxi.transform.position=site.Bay;UnityEngine.Time.time=40;s.services.TickFacilityQueue();Check(s.services.QueueStatus!="","host treats remote human seat as player for physical facility admission");}finally{PvpNativeLan.Remote=false;}}
 static void CheapFacilitySnapshot(){var match=new PvpSimulationMatch();var s=Session(match);var other=Session(match);var site=Site();s.services.Stations.Add(new FuelStationLayout.FuelStation{approach=site.Approach,pump=site.Bay,direction=site.Direction,drivePath=new[]{site.Approach.V(),site.Bay,site.Bay+site.Direction*20}});other.services.CanEnterFacility(site);OperationForecastAdapter.DirectedCalls=0;UnityEngine.Physics.Blocked=true;try{var views=s.services.CaptureFacilityQueues();FacilityQueueView found=null;foreach(var view in views)if(view.id==site.Id)found=view;Check(found!=null&&found.waiting==1&&found.occupied,"snapshot reports shared FIFO and real bay occupancy");s.services.CaptureFacilityQueues();Check(OperationForecastAdapter.DirectedCalls==0,"periodic queue snapshots must not calculate routes or quotes");}finally{UnityEngine.Physics.Blocked=false;}}
 static void UnreachableLateRest(){ProjectMapScene.Authored=true;try{var s=Session(new PvpSimulationMatch{Remaining=30});s.business.ledger.EnablePvpProfile();s.business.ledger.Driver.fatigue=99;var bot=new PvpSimulationBotServices();Check(!bot.Tick(s),"late predicted fatigue with no reachable recovery must not hold bot indefinitely");}finally{ProjectMapScene.Authored=false;}}
 static void DepartureKeepsCriticalControl(){for(int scenario=0;scenario<3;scenario++){
  var s=Session(new PvpSimulationMatch());var e=s.business.ledger;
  if(scenario<2)e.Account.Consume(0,59000/4);
  if(scenario==0){e.Care.Damage.Impact(16);e.Care.Damage.Advance(1,false);e.Care.Damage.Impact(12);Check(e.Care.Damage.Durability<=20,"repair fixture simultaneous damage/fuel critical");Check(e.UseRepair("prior-repair"),"native planned repair completed before departure");Check(e.Account.Fuel<8,"fuel remains critical after paid repair");}
  if(scenario==1){e.Driver.fatigue=90;Check(e.Account.Refuel("prior-fuel",10,1),"one native fuel purchase completed before departure");e.AdvanceService(10);Check(e.Driver.fatigue>=90,"fatigue remains critical after paid fuel");}
  var bot=new PvpSimulationBotServices();Set(bot,"stage",4);Set(bot,"manoeuvre",new AssistedRoadNetwork.Path(new[]{UnityEngine.Vector3.zero,UnityEngine.Vector3.forward*50}));Set(bot,"progress",49.9f);
  int expenses=e.Account.Expense(1,null);double elapsed=e.Elapsed;bool controlsCaller=bot.Tick(s);
  Check(controlsCaller==(scenario<2),"departure Tick must hold actual caller for remaining simultaneous critical state scenario="+scenario);
  Check(!bot.Active&&s.services.Bought.Count==0&&e.Account.Expense(1,null)==expenses&&e.Elapsed==elapsed,"departure ends old visit without free bundled action/charge/time");
  if(scenario<2){Check(s.taxi.autoBrake,"critical completed exit safely stops");Check((float)bot.GetType().GetField("retryAt",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(bot)<=UnityEngine.Time.time,"new service planning eligible on next Tick");Check(bot.Tick(s),"next Tick retains control while planning remaining critical need");}
 }}
 public static int Main(string[] args){try{if(args.Length==0||args[0]=="critical")CriticalCaller();if(args.Length==0||args[0]=="advance")EntranceAdvances();if(args.Length==0||args[0]=="cancel")CancelStaysCanceled();if(args.Length==0||args[0]=="plan")ExecutesPlanOnly();if(args.Length==0||args[0]=="travel")DrivewayBudget();if(args.Length==0||args[0]=="meal")MealThroughAccess();if(args.Length==0||args[0]=="remote")RemoteHumanQueues();if(args.Length==0||args[0]=="snapshot")CheapFacilitySnapshot();if(args.Length==0||args[0]=="late")UnreachableLateRest();if(args.Length==0||args[0]=="departure")DepartureKeepsCriticalControl();Console.WriteLine("OPERATION_ADAPTER_OK "+(args.Length==0?"all":args[0]));return 0;}catch(Exception e){Console.WriteLine(e.Message);return 1;}}
}
